/* =========================================================
   Moss — gentle household plant care
   Plain ES5-ish browser JS. No dependencies, no network
   (PLANTS.json is fetched only when served over http, and a
   copy lives here so file:// works too).
   ========================================================= */
(function () {
  'use strict';

  /* ---------------------------------------------------------
     1. Data
     --------------------------------------------------------- */

  var EMBEDDED = {
    "plants": [
      {"id":"fern","name":"Frida","species":"Boston fern","location":"Bathroom","task":"Water","due":"2 days overdue","urgency":4,"light":"Low, indirect","history":["Sep 19 · Misted","Sep 16 · Watered","Sep 12 · New frond"]},
      {"id":"pothos","name":"Orbit","species":"Golden pothos","location":"Bookshelf","task":"Rotate","due":"Today","urgency":2,"light":"Medium, indirect","history":["Sep 20 · Watered","Sep 14 · Rotated","Sep 10 · Wiped leaves"]},
      {"id":"cactus","name":"Dot","species":"Bunny ears cactus","location":"South window","task":"Check soil","due":"Today","urgency":1,"light":"Bright, direct","history":["Sep 08 · Watered","Sep 01 · New pad noted","Aug 22 · Rotated"]},
      {"id":"calathea","name":"Drama","species":"Calathea orbifolia","location":"Bedroom","task":"Mist","due":"Tomorrow","urgency":0,"light":"Medium, filtered","history":["Sep 21 · Misted","Sep 18 · Watered","Sep 15 · Brown edge noted"]}
    ],
    "week": [1, 3, 2, 4, 2, 1, 3]
  };

  /* The fixture is written for this day; everything is derived from it. */
  var TODAY = { label: 'Wednesday · Sep 23', year: 2026, month: 8, day: 23, dow: 2 };
  var DAY_FULL = ['Monday', 'Tuesday', 'Wednesday', 'Thursday', 'Friday', 'Saturday', 'Sunday'];
  var DAY_SHORT = ['Mo', 'Tu', 'We', 'Th', 'Fr', 'Sa', 'Su'];
  var MONTHS = { Jan: 0, Feb: 1, Mar: 2, Apr: 3, May: 4, Jun: 5, Jul: 6, Aug: 7, Sep: 8, Oct: 9, Nov: 10, Dec: 11 };

  var VERBS = { 'Water': 'Watered', 'Rotate': 'Rotated', 'Check soil': 'Checked', 'Mist': 'Misted' };
  var WASH = { fern: 'var(--wash-fern)', pothos: 'var(--wash-pothos)', cactus: 'var(--wash-cactus)', calathea: 'var(--wash-calathea)' };

  var reduceMotion = window.matchMedia('(prefers-reduced-motion: reduce)');

  /* ---------------------------------------------------------
     2. Tiny helpers
     --------------------------------------------------------- */

  function esc(s) {
    return String(s).replace(/[&<>"']/g, function (c) {
      return { '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c];
    });
  }
  function $(id) { return document.getElementById(id); }
  function round(n) { return Math.round(n * 10) / 10; }
  function listWords(names) {
    if (names.length === 1) return names[0];
    return names.slice(0, -1).join(', ') + ' and ' + names[names.length - 1];
  }
  function plural(n, one, many) { return n + ' ' + (n === 1 ? one : many); }

  function daysAgo(dateString) {
    var parts = String(dateString).split(/\s+/);
    var m = MONTHS[parts[0]];
    if (m == null || !parts[1]) return null;
    var then = new Date(TODAY.year, m, parseInt(parts[1], 10));
    var now = new Date(TODAY.year, TODAY.month, TODAY.day);
    return Math.round((now - then) / 86400000);
  }

  /* quadratic / cubic sampling, used to grow leaves along a stem */
  function qPoint(p0, c, p1, t) {
    var u = 1 - t;
    return [u * u * p0[0] + 2 * u * t * c[0] + t * t * p1[0], u * u * p0[1] + 2 * u * t * c[1] + t * t * p1[1]];
  }
  function qTan(p0, c, p1, t) {
    return [2 * (1 - t) * (c[0] - p0[0]) + 2 * t * (p1[0] - c[0]),
            2 * (1 - t) * (c[1] - p0[1]) + 2 * t * (p1[1] - c[1])];
  }
  function cPoint(p0, c1, c2, p1, t) {
    var u = 1 - t;
    return [u * u * u * p0[0] + 3 * u * u * t * c1[0] + 3 * u * t * t * c2[0] + t * t * t * p1[0],
            u * u * u * p0[1] + 3 * u * u * t * c1[1] + 3 * u * t * t * c2[1] + t * t * t * p1[1]];
  }

  /* ---------------------------------------------------------
     3. Illustration — every plant is drawn with inline SVG
     --------------------------------------------------------- */

  var POT =
    '<rect x="13" y="38" width="38" height="9" rx="4" fill="var(--clay)"/>' +
    '<path d="M16.5 46h31l-3.4 18.1a4 4 0 0 1-3.9 3.4H23.8a4 4 0 0 1-3.9-3.4L16.5 46Z" fill="var(--clay-deep)"/>' +
    '<path d="M22.4 51.5l-1.5 11.5" stroke="rgba(255,246,238,.4)" stroke-width="2" stroke-linecap="round"/>';

  /* Frida — a fan of feathery fronds */
  function fern() {
    var base = [32, 38], out = [];
    var fronds = [
      { x: 5, y: 12, cx: 18, cy: 22 },
      { x: 15, y: 3, cx: 25, cy: 14 },
      { x: 32, y: 0.5, cx: 32, cy: 13 },
      { x: 49, y: 3, cx: 39, cy: 14 },
      { x: 59, y: 12, cx: 46, cy: 22 }
    ];
    fronds.forEach(function (f) {
      out.push('<path d="M32 38 Q' + f.cx + ' ' + f.cy + ' ' + f.x + ' ' + f.y + '" fill="none" stroke="var(--leaf-deep)" stroke-width="1.5" stroke-linecap="round"/>');
    });
    fronds.forEach(function (f, i) {
      for (var s = 1; s <= 5; s++) {
        var t = s / 5.4;
        var p = qPoint(base, [f.cx, f.cy], [f.x, f.y], t);
        var tan = qTan(base, [f.cx, f.cy], [f.x, f.y], t);
        var ang = Math.atan2(tan[1], tan[0]) * 180 / Math.PI;
        var rx = 4.6 * (1 - 0.5 * t);
        [-68, 68].forEach(function (side) {
          out.push('<ellipse cx="0" cy="0" rx="' + round(rx) + '" ry="' + round(rx * 0.45) +
            '" fill="' + (i % 2 ? 'var(--leaf)' : 'var(--leaf-2)') +
            '" transform="translate(' + round(p[0]) + ' ' + round(p[1]) + ') rotate(' + Math.round(ang + side) + ')"/>');
        });
      }
    });
    return out.join('');
  }

  /* Orbit — heart leaves on a vine that trails over the pot */
  function pothos() {
    var out = [];
    var heart = 'M0 4C-5 0-8-5-4-8c2-1.4 3.4-.2 4-1.4.6-1.2 2-2.4 4-1.4 4 3 1 8-4 12Z';
    function leaf(x, y, s, rot, fill) {
      return '<path d="' + heart + '" fill="' + fill + '" transform="translate(' + x + ' ' + y + ') rotate(' + rot + ') scale(' + s + ')"/>';
    }
    out.push('<path d="M32 38 C33 30 30 24 27 20" fill="none" stroke="var(--leaf-deep)" stroke-width="1.5" stroke-linecap="round"/>');
    out.push('<path d="M32 38 C36 32 40 27 44 24" fill="none" stroke="var(--leaf-deep)" stroke-width="1.5" stroke-linecap="round"/>');
    out.push(leaf(25, 21, 1.25, -20, 'var(--leaf)'));
    out.push(leaf(45, 22, 1.15, 20, 'var(--leaf-2)'));
    out.push(leaf(33, 29, 1, 4, 'var(--leaf-deep)'));

    /* the trailing vine */
    var p0 = [32, 38], c1 = [50, 40], c2 = [58, 52], p1 = [46, 66];
    out.push('<path d="M32 38 C50 40 58 52 46 66" fill="none" stroke="var(--leaf-deep)" stroke-width="1.4" stroke-linecap="round"/>');
    [0.18, 0.42, 0.66, 0.88].forEach(function (t, i) {
      var p = cPoint(p0, c1, c2, p1, t);
      out.push(leaf(round(p[0]), round(p[1]), 0.95 - i * 0.16, 24 + i * 12, i % 2 ? 'var(--leaf-2)' : 'var(--leaf)'));
    });
    return out.join('');
  }

  /* Dot — stacked pads with little areole dots */
  function cactus() {
    var out = [];
    var pads = [
      { cx: 32, cy: 24, rx: 10, ry: 14, rot: 0, rows: 3 },
      { cx: 20, cy: 13, rx: 5.6, ry: 9, rot: -26, rows: 2 },
      { cx: 44, cy: 12, rx: 5.6, ry: 9, rot: 26, rows: 2 },
      { cx: 47, cy: 27, rx: 4.4, ry: 6.5, rot: 40, rows: 2 },
      { cx: 32, cy: 6, rx: 4.2, ry: 5.6, rot: 0, rows: 1 }
    ];
    pads.forEach(function (pad, i) {
      out.push('<g transform="rotate(' + pad.rot + ' ' + pad.cx + ' ' + pad.cy + ')">' +
        '<ellipse cx="' + pad.cx + '" cy="' + pad.cy + '" rx="' + pad.rx + '" ry="' + pad.ry +
        '" fill="' + (i % 2 ? 'var(--leaf-2)' : 'var(--leaf)') + '"/>');
      for (var r = 0; r < pad.rows; r++) {
        var ry = pad.cy + (r - (pad.rows - 1) / 2) * (pad.ry * 0.62);
        [-0.42, 0.42].forEach(function (c) {
          out.push('<circle cx="' + round(pad.cx + c * pad.rx) + '" cy="' + round(ry) + '" r="0.95" fill="#FBF5EA" opacity=".85"/>');
        });
      }
      out.push('</g>');
    });
    return out.join('');
  }

  /* Drama — big striped rounds */
  function calathea() {
    var out = [];
    function stripedLeaf(cx, cy, rx, ry, rot, fill) {
      var s = '<g transform="rotate(' + rot + ' ' + cx + ' ' + cy + ')">';
      s += '<ellipse cx="' + cx + '" cy="' + cy + '" rx="' + rx + '" ry="' + ry + '" fill="' + fill + '"/>';
      for (var i = -3; i <= 3; i++) {
        if (i === 0) continue;
        var f = i * 0.26;
        var half = rx * Math.sqrt(Math.max(0, 1 - f * f)) * 0.88;
        var y = cy + f * ry;
        s += '<path d="M' + round(cx - half) + ' ' + round(y) + ' Q' + cx + ' ' + round(y + 2.2) + ' ' + round(cx + half) + ' ' + round(y) +
          '" fill="none" stroke="#FBF5EA" stroke-width="1.5" opacity=".55" stroke-linecap="round"/>';
      }
      s += '<path d="M' + round(cx - rx * 0.85) + ' ' + cy + 'H' + round(cx + rx * 0.85) + '" stroke="#FBF5EA" stroke-width="1.3" opacity=".45"/>';
      s += '</g>';
      return s;
    }
    out.push('<path d="M32 38 C30 32 26 28 21 25" fill="none" stroke="var(--leaf-deep)" stroke-width="1.6" stroke-linecap="round"/>');
    out.push('<path d="M32 38 C34 30 39 25 45 22" fill="none" stroke="var(--leaf-deep)" stroke-width="1.6" stroke-linecap="round"/>');
    out.push('<path d="M32 38 C32 32 32 29 32 27" fill="none" stroke="var(--leaf-deep)" stroke-width="1.6" stroke-linecap="round"/>');
    out.push(stripedLeaf(20, 21, 13, 11, -14, 'var(--leaf)'));
    out.push(stripedLeaf(46, 18, 12, 10.5, 14, 'var(--leaf-2)'));
    out.push(stripedLeaf(32, 30, 10.5, 8.5, 2, 'var(--leaf-deep)'));
    return out.join('');
  }

  var GLYPHS = { fern: fern, pothos: pothos, cactus: cactus, calathea: calathea };

  function glyph(id, cls) {
    var draw = GLYPHS[id] || fern;
    return '<svg viewBox="0 0 64 72" focusable="false" aria-hidden="true" class="' + (cls || '') + '">' + draw() + POT + '</svg>';
  }

  /* ---------------------------------------------------------
     4. Icons
     --------------------------------------------------------- */

  var ICON = {
    water: '<svg viewBox="0 0 16 16" aria-hidden="true" focusable="false"><path d="M8 2.2c2.6 3.1 4 5 4 6.6a4 4 0 0 1-8 0c0-1.6 1.4-3.5 4-6.6Z" fill="currentColor"/></svg>',
    rotate: '<svg viewBox="0 0 16 16" aria-hidden="true" focusable="false"><path d="M12.6 8.6A5 5 0 1 1 11 4.2" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round"/><path d="M13.8 1.6v3.4h-3.4" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round"/></svg>',
    soil: '<svg viewBox="0 0 16 16" aria-hidden="true" focusable="false"><circle cx="7" cy="7" r="4.2" fill="none" stroke="currentColor" stroke-width="1.6"/><path d="M10.2 10.2l3.6 3.6" stroke="currentColor" stroke-width="1.6" stroke-linecap="round"/></svg>',
    mist: '<svg viewBox="0 0 16 16" aria-hidden="true" focusable="false"><path d="M4 5c1.2 1.5 1.8 2.4 1.8 3a1.8 1.8 0 1 1-3.6 0C2.2 7.4 2.8 6.5 4 5Z" fill="currentColor"/><circle cx="9.2" cy="4.6" r="1" fill="currentColor"/><circle cx="11.8" cy="7.6" r="1.3" fill="currentColor"/><circle cx="8.6" cy="10.4" r="1" fill="currentColor"/></svg>',
    leaf: '<svg viewBox="0 0 16 16" aria-hidden="true" focusable="false"><path d="M8 14S2 11 2 6.4C2 3.6 4.5 1.6 8 1.6s6 2 6 4.8C14 11 8 14 8 14Z" fill="currentColor"/></svg>',
    moon: '<svg viewBox="0 0 16 16" aria-hidden="true" focusable="false"><path d="M10.8 2.2a6 6 0 1 0 3.2 7.4A5 5 0 0 1 10.8 2.2Z" fill="currentColor"/></svg>',
    sun: '<svg viewBox="0 0 16 16" aria-hidden="true" focusable="false"><circle cx="8" cy="8" r="3" fill="currentColor"/><g stroke="currentColor" stroke-width="1.4" stroke-linecap="round"><path d="M8 1v2M8 13v2M1 8h2M13 8h2M3 3l1.4 1.4M11.6 11.6L13 13M13 3l-1.4 1.4M4.4 11.6L3 13"/></g></svg>'
  };
  function taskIcon(task) {
    if (task === 'Water') return ICON.water;
    if (task === 'Rotate') return ICON.rotate;
    if (task === 'Check soil') return ICON.soil;
    if (task === 'Mist') return ICON.mist;
    return ICON.leaf;
  }

  /* ---------------------------------------------------------
     5. Model
     --------------------------------------------------------- */

  var plants = [];
  var byId = {};
  var week = [];
  var trail = [];      /* action history, for "undo last" */
  var viaKeyboard = false;

  function buildModel(data) {
    week = data.week || [];
    plants = (data.plants || []).map(function (p) {
      var history = (p.history || []).map(function (h) {
        var bits = String(h).split('·');
        return { date: bits[0].trim(), note: bits.slice(1).join('·').trim() };
      });
      var watered = null;
      for (var i = 0; i < history.length; i++) {
        if (/water/i.test(history[i].note)) { watered = history[i]; break; }
      }
      var light = String(p.light || '');
      return {
        id: p.id,
        name: p.name,
        species: p.species,
        location: p.location,
        task: p.task,
        due: p.due,
        urgency: p.urgency || 0,
        light: light,
        history: history,
        verb: VERBS[p.task] || p.task,
        dueKind: p.urgency >= 4 ? 'overdue' : (p.urgency >= 1 ? 'today' : 'soon'),
        group: p.urgency >= 1 ? 'now' : 'next',
        lightLevel: /^Low/.test(light) ? 1 : (/^Medium/.test(light) ? 2 : 3),
        watered: watered,
        waterDays: watered ? daysAgo(watered.date) : null,
        status: 'due',      /* due | snoozed | done */
        open: false
      };
    });
    byId = {};
    plants.forEach(function (p) { byId[p.id] = p; });
  }

  /* ---------------------------------------------------------
     6. Markup
     --------------------------------------------------------- */

  function chipsHTML(p) {
    var out = '<span class="chip chip--task">' + taskIcon(p.task) + esc(p.task) + '</span>';
    if (p.status === 'snoozed') {
      out += '<span class="chip chip--snoozed">Snoozed · tomorrow</span>';
    } else if (p.dueKind === 'overdue') {
      out += '<span class="chip chip--over">' + esc(p.due) + '</span>';
    } else if (p.dueKind === 'today') {
      out += '<span class="chip chip--today">Due today</span>';
    } else {
      out += '<span class="chip chip--soon">' + esc(p.due) + '</span>';
    }
    return out;
  }

  function actionsHTML(p) {
    if (p.status === 'done') return '';
    if (p.status === 'snoozed') {
      return '<div class="plant__actions">' +
        '<button class="btn btn--ghost" type="button" data-act="wake" data-id="' + p.id + '" aria-label="Wake ' + esc(p.name) + ' — put back on today\'s list">' + ICON.sun + 'Wake up</button>' +
        '</div>';
    }
    var icon = (p.task === 'Water' || p.task === 'Mist') ? ICON.water : ICON.leaf;
    return '<div class="plant__actions">' +
      '<button class="btn btn--primary" type="button" data-act="done" data-id="' + p.id + '" aria-label="Mark ' + esc(p.name) + ' as ' + esc(p.verb.toLowerCase()) + '">' + icon + esc(p.verb) + '</button>' +
      '<button class="btn btn--ghost" type="button" data-act="snooze" data-id="' + p.id + '" aria-label="Snooze ' + esc(p.name) + ' until tomorrow">' + ICON.moon + 'Snooze</button>' +
      '</div>';
  }

  function detailHTML(p) {
    var dots = '';
    for (var i = 1; i <= 3; i++) {
      dots += '<i data-on="' + (i <= p.lightLevel ? '1' : '0') + '"></i>';
    }
    var waterValue = p.waterDays == null ? 'No drink logged yet'
      : (p.waterDays === 0 ? 'Watered today' : plural(p.waterDays, 'day', 'days') + ' since the last drink');
    var waterSub = p.watered ? 'Last watered ' + esc(p.watered.date) : 'Moss has no record — check the soil';
    var items = p.history.map(function (h) {
      return '<li><span class="timeline__date">' + esc(h.date) + '</span><span class="timeline__note">' + esc(h.note) + '</span></li>';
    }).join('');

    return '<div class="facts">' +
      '<div class="fact">' +
        '<h4>Light</h4>' +
        '<p class="fact__value">' + esc(p.light) + '</p>' +
        '<span class="dots" role="img" aria-label="Light level ' + p.lightLevel + ' of 3">' + dots + '</span>' +
      '</div>' +
      '<div class="fact">' +
        '<h4>Water</h4>' +
        '<p class="fact__value">' + waterValue + '</p>' +
        '<p class="fact__sub">' + waterSub + '</p>' +
      '</div>' +
    '</div>' +
    '<h4 class="detail__label">Observation history</h4>' +
    '<ol class="timeline">' + items + '</ol>' +
    '<p class="detail__foot">Lives in the ' + esc(p.location) + ' · ' + esc(p.species) + '</p>';
  }

  function rowHTML(p) {
    var open = p.open ? '1' : '0';
    return '<li class="plant" data-id="' + p.id + '" data-open="' + open + '" data-due="' + (p.status === 'due' ? p.dueKind : '') + '">' +
      '<div class="plant__row">' +
        '<h4 class="plant__h">' +
          '<button class="plant__toggle" type="button" aria-expanded="' + (p.open ? 'true' : 'false') + '" aria-controls="detail-' + p.id + '">' +
            '<span class="glyph" style="--wash:' + WASH[p.id] + '">' + glyph(p.id) + '</span>' +
            '<span class="plant__id">' +
              '<span class="plant__name">' + esc(p.name) + '</span>' +
              '<span class="plant__meta">' + esc(p.species) + ' · ' + esc(p.location) + '</span>' +
              '<span class="plant__chips">' + chipsHTML(p) + '</span>' +
            '</span>' +
            '<span class="plant__chev"><svg viewBox="0 0 16 16" aria-hidden="true" focusable="false"><path d="M4 6.2l4 4 4-4" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"/></svg></span>' +
          '</button>' +
        '</h4>' +
        actionsHTML(p) +
      '</div>' +
      '<div class="detail" id="detail-' + p.id + '"' + (p.open ? '' : ' hidden') + '>' + detailHTML(p) + '</div>' +
    '</li>';
  }

  function doneRowHTML(p) {
    return '<li>' +
      '<span class="done__glyph" style="--wash:' + WASH[p.id] + '">' + glyph(p.id) + '</span>' +
      '<span class="done__text"><strong>' + esc(p.name) + '</strong> <span>· ' + esc(p.verb.toLowerCase()) + '</span></span>' +
      '<button class="btn btn--quiet" type="button" data-act="undo" data-id="' + p.id + '" aria-label="Undo — put ' + esc(p.name) + ' back on today\'s list">Undo</button>' +
    '</li>';
  }

  /* ---------------------------------------------------------
     7. Render
     --------------------------------------------------------- */

  function render() {
    var nowAll = plants.filter(function (p) { return p.group === 'now'; });
    var nextAll = plants.filter(function (p) { return p.group === 'next'; });

    var dueNow = nowAll.filter(function (p) { return p.status === 'due'; })
      .sort(function (a, b) { return b.urgency - a.urgency; });
    var snoozedNow = nowAll.filter(function (p) { return p.status === 'snoozed'; });
    var pendingNext = nextAll.filter(function (p) { return p.status !== 'done'; });
    var doneAll = plants.filter(function (p) { return p.status === 'done'; });
    var doneNow = nowAll.filter(function (p) { return p.status === 'done'; });

    $('listNow').innerHTML = dueNow.concat(snoozedNow).map(rowHTML).join('');
    $('listNext').innerHTML = pendingNext.map(rowHTML).join('');
    $('groupNow').hidden = dueNow.length + snoozedNow.length === 0;
    $('groupNext').hidden = pendingNext.length === 0;
    $('queue').hidden = $('groupNow').hidden && $('groupNext').hidden;

    /* done list */
    $('listDone').innerHTML = doneAll.map(doneRowHTML).join('');
    $('doneSection').hidden = doneAll.length === 0;

    /* all-done state */
    var clear = nowAll.every(function (p) { return p.status !== 'due'; });
    $('allDone').hidden = !clear;
    if (clear) {
      var doneNames = doneNow.map(function (p) { return p.name; });
      var napNames = nowAll.filter(function (p) { return p.status === 'snoozed'; }).map(function (p) { return p.name; });
      var bits = [];
      if (doneNames.length) bits.push(listWords(doneNames) + (doneNames.length === 1 ? ' is' : ' are') + ' topped up');
      if (napNames.length) bits.push(listWords(napNames) + (napNames.length === 1 ? ' waits' : ' wait') + ' until tomorrow');
      if (pendingNext.length) bits.push(listWords(pendingNext.map(function (p) { return p.name; })) + ' needs nothing today');
      $('allDoneTitle').textContent = doneNames.length === 0 ? 'Everything is parked for tomorrow' : 'Every leaf is content';
      $('allDoneText').textContent = bits.length ? bits.join('. ') + '.' : 'Nothing is waiting on you.';
      var undoLast = $('allDone').querySelector('[data-act="undo-last"]');
      undoLast.hidden = trail.length === 0;
    }

    /* hero + meter */
    var overdue = dueNow.filter(function (p) { return p.dueKind === 'overdue'; });
    var sub;
    if (dueNow.length === 0) {
      sub = snoozedNow.length
        ? 'Nothing due today. ' + plural(snoozedNow.length, 'plant', 'plants') + ' parked for tomorrow.'
        : 'Nothing due today. Go look at them anyway.';
    } else if (overdue.length) {
      sub = plural(dueNow.length, 'plant', 'plants') + ' waiting — ' + listWords(overdue.map(function (p) { return p.name; })) +
        (overdue.length === 1 ? ' is' : ' are') + ' overdue.';
    } else {
      sub = plural(dueNow.length, 'plant', 'plants') + ' to go, and nobody is behind yet.';
    }
    $('heroSub').textContent = sub;

    var total = nowAll.length || 1;
    var pct = Math.round(doneNow.length / total * 100);
    $('meterFill').style.setProperty('--p', pct + '%');
    $('meter').setAttribute('aria-valuenow', String(doneNow.length));
    $('meter').setAttribute('aria-valuemax', String(total));
    $('meter').setAttribute('aria-valuetext', doneNow.length + ' of ' + total + ' done');
    $('meter').dataset.on = doneNow.length > 0 ? '1' : '0';
    $('meterText').textContent = doneNow.length + ' of ' + total + ' done today';
  }

  function renderRhythm() {
    var max = week.reduce(function (m, v) { return Math.max(m, v); }, 1);
    var total = week.reduce(function (s, v) { return s + v; }, 0);
    var busiest = 0;
    week.forEach(function (v, i) { if (v > week[busiest]) busiest = i; });

    $('rhythm').innerHTML = week.map(function (v, i) {
      var dots = '';
      for (var d = 0; d < max; d++) {
        dots += '<span class="dot" data-on="' + (d < v ? '1' : '0') + '"></span>';
      }
      var today = i === TODAY.dow ? '1' : '0';
      return '<li data-today="' + today + '">' +
        '<span class="day__stack" aria-hidden="true">' + dots + '</span>' +
        '<span class="day__label">' + DAY_SHORT[i] + '</span>' +
        '<span class="sr-only">' + DAY_FULL[i] + ': ' + plural(v, 'care moment', 'care moments') +
        (i === TODAY.dow ? ' (today)' : '') + '</span>' +
      '</li>';
    }).join('');

    $('rhythmNote').textContent = plural(total, 'care moment', 'care moments') + ' this week — ' +
      DAY_FULL[busiest] + ' is the busiest. Dots stack from the soil up.';
  }

  /* ---------------------------------------------------------
     8. Feedback: toast, live region, small delight
     --------------------------------------------------------- */

  var toast = null, toastTimer = null;

  function say(text) { $('live').textContent = text; }

  function showToast(message, undoId) {
    toast = { id: undoId };
    $('toastMsg').textContent = message;
    var t = $('toast');
    t.hidden = false;
    $('toastUndo').hidden = !undoId;
    /* restart the entrance animation */
    t.style.animation = 'none';
    void t.offsetWidth;
    t.style.animation = '';
    clearTimeout(toastTimer);
    toastTimer = setTimeout(hideToast, 7000);
    if (viaKeyboard && undoId) $('toastUndo').focus();
  }

  function hideToast() {
    clearTimeout(toastTimer);
    var t = $('toast');
    if (t.hidden) return;
    var refocus = t.contains(document.activeElement);
    t.hidden = true;
    toast = null;
    if (refocus) {
      var next = document.querySelector('.plant__toggle');
      if (next) next.focus();
    }
  }

  function plop(el, kind) {
    if (reduceMotion.matches) return;
    var r = el.getBoundingClientRect();
    var s = document.createElement('span');
    s.className = 'plop';
    s.style.left = (r.left + r.width / 2) + 'px';
    s.style.top = (r.top - 4) + 'px';
    s.innerHTML = kind === 'leaf' ? ICON.leaf : ICON.water;
    document.body.appendChild(s);
    setTimeout(function () { s.remove(); }, 700);
  }

  /* ---------------------------------------------------------
     9. Actions
     --------------------------------------------------------- */

  function apply(id, act) {
    var p = byId[id];
    if (!p) return;
    var prev = p.status;
    var message;

    if (act === 'done') {
      p.status = 'done';
      p.open = false;
      message = p.verb + ' ' + p.name + '. Nice.';
    } else if (act === 'snooze') {
      p.status = 'snoozed';
      p.open = false;
      message = 'Snoozed ' + p.name + ' until tomorrow.';
    } else if (act === 'wake' || act === 'undo') {
      p.status = 'due';
      message = p.name + ' is back on today\'s list.';
    } else {
      return;
    }

    trail.push({ id: id, prev: prev, next: p.status });
    render();
    say(message + ' Undo is available.');
    showToast(message, id);
  }

  function undoLast() {
    var step = trail.pop();
    if (!step) return;
    var p = byId[step.id];
    p.status = step.prev;
    render();
    hideToast();
    say('Undone — ' + p.name + ' is back on today\'s list.');
    restoreFocus(step.id);
  }

  function resetDay() {
    trail.length = 0;
    plants.forEach(function (p) { p.status = 'due'; });
    render();
    hideToast();
    say('The day is fresh again. Four plants are waiting.');
    var first = document.querySelector('.plant__toggle');
    if (first) first.focus();
  }

  function restoreFocus(id) {
    var li = document.querySelector('.plant[data-id="' + id + '"]');
    if (!li) return;
    var target = li.querySelector('[data-act="done"]') || li.querySelector('.plant__toggle');
    if (target) target.focus();
  }

  function togglePlant(id, force) {
    var p = byId[id];
    if (!p) return;
    p.open = typeof force === 'boolean' ? force : !p.open;
    var li = document.querySelector('.plant[data-id="' + id + '"]');
    if (!li) return;
    li.dataset.open = p.open ? '1' : '0';
    li.querySelector('.plant__toggle').setAttribute('aria-expanded', p.open ? 'true' : 'false');
    li.querySelector('.detail').hidden = !p.open;
  }

  /* ---------------------------------------------------------
     10. Events
     --------------------------------------------------------- */

  document.addEventListener('pointerdown', function () { viaKeyboard = false; }, true);
  document.addEventListener('keydown', function (e) {
    if (e.key === 'Tab' || e.key.indexOf('Arrow') === 0 || e.key === 'Enter' || e.key === ' ' || e.key === 'Escape') {
      viaKeyboard = true;
    }
  }, true);

  document.addEventListener('click', function (e) {
    var toggle = e.target.closest ? e.target.closest('.plant__toggle') : null;
    if (toggle) {
      var host = toggle.closest('.plant');
      togglePlant(host.dataset.id);
      return;
    }
    var btn = e.target.closest ? e.target.closest('[data-act]') : null;
    if (!btn) return;
    var act = btn.dataset.act;
    var id = btn.dataset.id;

    if (act === 'undo-last') { undoLast(); return; }
    if (act === 'reset') { resetDay(); return; }
    if (act === 'undo') { apply(id, 'undo'); return; }

    var p = byId[id];
    if (act === 'done') {
      plop(btn, (p && (p.task === 'Rotate' || p.task === 'Check soil')) ? 'leaf' : 'water');
    }
    apply(id, act);
  });

  $('toastUndo').addEventListener('click', function () { undoLast(); });
  $('toastClose').addEventListener('click', function () { hideToast(); });
  ['mouseenter', 'focusin'].forEach(function (ev) {
    $('toast').addEventListener(ev, function () { clearTimeout(toastTimer); });
  });
  ['mouseleave', 'focusout'].forEach(function (ev) {
    $('toast').addEventListener(ev, function () {
      if (!$('toast').hidden) toastTimer = setTimeout(hideToast, 3000);
    });
  });

  /* keyboard: arrow keys walk the queue, ← / → fold and unfold */
  document.addEventListener('keydown', function (e) {
    var list = e.target.closest ? e.target.closest('.plants') : null;
    if (!list) return;
    var toggle = e.target.closest('.plant__toggle');
    if (!toggle) return;
    var items = Array.prototype.slice.call(list.querySelectorAll('.plant__toggle'));
    var i = items.indexOf(toggle);
    var id = toggle.closest('.plant').dataset.id;

    if (e.key === 'ArrowDown') {
      if (items[i + 1]) { items[i + 1].focus(); e.preventDefault(); }
    } else if (e.key === 'ArrowUp') {
      if (items[i - 1]) { items[i - 1].focus(); e.preventDefault(); }
    } else if (e.key === 'Home') {
      items[0].focus(); e.preventDefault();
    } else if (e.key === 'End') {
      items[items.length - 1].focus(); e.preventDefault();
    } else if (e.key === 'ArrowRight') {
      if (!byId[id].open) togglePlant(id, true);
      e.preventDefault();
    } else if (e.key === 'ArrowLeft') {
      if (byId[id].open) togglePlant(id, false);
      e.preventDefault();
    } else if (e.key === 'Escape') {
      if (byId[id].open) { togglePlant(id, false); e.preventDefault(); }
    }
  });

  /* ---------------------------------------------------------
     11. Boot
     --------------------------------------------------------- */

  function loadPlants() {
    var proto = location.protocol;
    if (proto === 'http:' || proto === 'https:') {
      return fetch('PLANTS.json').then(function (r) {
        if (!r.ok) throw new Error('no json');
        return r.json();
      }).catch(function () { return EMBEDDED; });
    }
    return Promise.resolve(EMBEDDED);
  }

  loadPlants().then(function (data) {
    buildModel(data);
    $('dateLabel').textContent = TODAY.label;
    renderRhythm();
    render();
  });
})();

